// MIT. x402 v2 Bazaar discovery-core prototype: no settlement or external registrations.
import { createHash } from 'node:crypto';
import { isIP } from 'node:net';
import { inspectResourceURL, inspectRouteTemplate } from '../../stellar-forge/route-identity/identity.mjs';
import { CatalogQueryIndex } from './query-index.mjs';
import { sanitizeBazaarPricing, parseAtomicBudget, describeCatalogPricing } from './pricing.mjs';

const plain = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const printable = (v) => typeof v === 'string' && v.length > 0 && v.length <= 32 && /^[\x20-\x7E]+$/.test(v);
const ALLOWED = new Set(['type','payTo','network','scheme','asset','extensions']);
// SF28 identity grammar also prevents pipe-delimited MCP catalog key aliasing.
const MCP_TOOL_NAME = /^[A-Za-z0-9_.-]{1,128}$/;

export function isValidRouteTemplate(template) {
  // Reuse SF28 multi-decode path validation at the actual catalog boundary.
  return inspectRouteTemplate(template).ok;
}

export function sanitizeResourceServiceMetadata(resource) {
  const result = { ...resource };
  if (!printable(result.serviceName)) delete result.serviceName;
  if (!Array.isArray(result.tags)) delete result.tags;
  else {
    const seen = new Set();
    result.tags = result.tags.filter(t => {
      if (!printable(t) || seen.has(t.toLowerCase())) return false;
      seen.add(t.toLowerCase());
      return seen.size <= 5;
    }).slice(0, 5);
  }
  if (typeof result.iconUrl === 'string') {
    try {
      if (result.iconUrl.length > 2048 || /[\x00-\x1f\x7f]/.test(result.iconUrl)) throw Error('invalid');
      const u = new URL(result.iconUrl);
      const h = decodeURIComponent(u.hostname).toLowerCase().replace(/\.$/,'');
      // Discovery consumers may fetch icons. Do not advertise explicitly local
      // DNS names as otherwise public-looking icon URLs; syntax-only protection,
      // not a substitute for a consumer's DNS/IP checks at fetch time.
      const localName = ['localhost','local','localdomain','internal','home.arpa',
        'ip6-localhost','ip6-loopback'].includes(h) ||
        ['.localhost','.local','.localdomain','.internal','.home.arpa'].some(s => h.endsWith(s));
      if (!['http:', 'https:'].includes(u.protocol) || u.username || u.password || isIP(h) ||
          localName || /^\d+$/.test(h) || /^0x[0-9a-f]+$/.test(h)) throw Error('invalid');
    } catch { delete result.iconUrl; }
  } else delete result.iconUrl;
  return result;
}

function filtersFrom(params) {
  const f = {};
  for (const k of ALLOWED) {
    const v = params.get(k);
    if (v !== null) f[k] = v;
  }
  return f;
}
function keyOf(entry) {
  const info = entry.extensions?.bazaar?.info?.input;
  if (!plain(info) || !['http','mcp'].includes(info.type)) throw new TypeError('Valid HTTP or MCP Bazaar info required');
  // Reject raw encoded traversal before WHATWG URL normalization.
  const checked = inspectResourceURL(entry.resource?.url);
  if (!checked.ok) throw new TypeError(`Invalid resource URL: ${checked.reason}`);
  const url = checked.url;
  if (info.type === 'mcp') {
    if (typeof info.toolName !== 'string' || !MCP_TOOL_NAME.test(info.toolName) || !plain(info.inputSchema)) throw new TypeError('Invalid MCP tool');
    return ['mcp',url.href,info.toolName].join('|');
  }
  if (!['GET','HEAD','DELETE','POST','PUT','PATCH'].includes(info.method)) throw new TypeError('Invalid HTTP method');
  // Different concrete path parameter values collapse to the same canonical entry.
  const template = inspectRouteTemplate(entry.extensions.bazaar.routeTemplate);
  const path = template.ok ? template.canonicalPath : url.pathname;
  return ['http',url.origin,path,url.search,info.method].join('|');
}

/**
 * Parse and sanitize a trusted-caller candidate without mutating a catalog.
 * Trust/sequence/ownership checks belong to the caller; this only applies the
 * same structural rules as insertValidated and returns the exact eventual key.
 */
export function validateCatalogEntry(entry) {
  if (!plain(entry?.resource) || !Array.isArray(entry.accepts) || entry.accepts.length === 0 ||
      !plain(entry.extensions?.bazaar) || !plain(entry.extensions.bazaar.info) ||
      !plain(entry.extensions.bazaar.schema)) throw new TypeError('Missing validated Bazaar envelope');
  if (entry.accepts.some(a => !plain(a) || typeof a.network !== 'string' || typeof a.scheme !== 'string' || typeof a.payTo !== 'string')) throw new TypeError('Invalid payment terms');
  const id = keyOf(entry);
  const sanitized = structuredClone(entry);
  sanitized.resource = sanitizeResourceServiceMetadata(sanitized.resource);
  // Proposed upstream optional pricing is catalog-only. Bad seller metadata
  // cannot invalidate an otherwise usable offer or leak unbounded hints.
  const pricing = sanitizeBazaarPricing(sanitized.extensions.bazaar.pricing);
  if (pricing === null) delete sanitized.extensions.bazaar.pricing;
  else sanitized.extensions.bazaar.pricing = pricing;
  const template = inspectRouteTemplate(sanitized.extensions.bazaar.routeTemplate);
  if (template.ok) sanitized.extensions.bazaar.routeTemplate = template.canonicalPath;
  else delete sanitized.extensions.bazaar.routeTemplate;
  return { id, entry: sanitized };
}
const signature = (query, filters) => createHash('sha256').update(JSON.stringify([query, filters])).digest('hex').slice(0,20);
const encode = (obj) => Buffer.from(JSON.stringify(obj)).toString('base64url');
const decode = (str) => {
  // Valid cursors are tiny canonical base64url JSON payloads. Validate length
  // and alphabet before decoding attacker-controlled input.
  if (typeof str !== 'string' || !str.length || str.length > 512 || !/^[A-Za-z0-9_-]+$/.test(str)) throw new RangeError('Invalid cursor');
  try {
    const raw = Buffer.from(str, 'base64url');
    if (raw.toString('base64url') !== str) throw new RangeError('Invalid cursor');
    return JSON.parse(raw.toString('utf8'));
  } catch {throw new RangeError('Invalid cursor');}
};
const asInteger = (v, fallback, max, min = 0) => {
  if (v === null) return fallback;
  if (!/^\d+$/.test(v) || !Number.isSafeInteger(Number(v)) || Number(v) < min || Number(v) > max) throw new RangeError('Invalid pagination parameter');
  return Number(v);
};

export class BazaarCatalog {
  #entries = new Map(); #version = 0;
  #queries = new CatalogQueryIndex(this.#entries);
  // Call only from a trusted post-verification facilitator hook AFTER checking the
  // settlement, seller/recipient binding, and JSON Schema Draft 2020-12. NEVER
  // route this method directly to an unauthenticated HTTP client or payment payload.
  insertValidated(entry) {
    const { id, entry: sanitized } = validateCatalogEntry(entry);
    const previous = this.#entries.get(id);
    this.#entries.set(id, sanitized); this.#version++;
    this.#queries.changed(id, previous, sanitized);
    return id;
  }
  /** Internal integration primitive: remove an already-authorized key. */
  removeValidated(id) {
    if (typeof id !== 'string') throw new TypeError('Catalog key required');
    const previous = this.#entries.get(id);
    const removed = this.#entries.delete(id);
    if (removed) { this.#version++; this.#queries.changed(id, previous, undefined); }
    return removed;
  }
  /** Stage an isolated transaction while preserving the cursor generation. */
  clone() {
    const copy = new BazaarCatalog();
    copy.#entries = new Map([...this.#entries].map(([key, value]) => [key, structuredClone(value)]));
    copy.#version = this.#version;
    copy.#queries = new CatalogQueryIndex(copy.#entries);
    return copy;
  }
  list(params = new URLSearchParams()) {
    const filters = filtersFrom(params);
    const offset = asInteger(params.get('offset'),0,1_000_000);
    const limit = asInteger(params.get('limit'),20,100,1);
    // The original ordering/filtering contract now reuses the private query index.
    const all = this.#queries.list(filters);
    // Public read results must not expose the authoritative mutable entry objects.
    // Clone only the returned page, not the whole filtered catalog.
    return { resources: all.slice(offset,offset+limit).map(row => structuredClone(row)),pagination:{offset,limit,total:all.length} };
  }
  search(params = new URLSearchParams()) {
    const q = params.get('query');
    if (typeof q !== 'string' || !q.trim() || q.length > 1024) throw new RangeError('query is required (max 1024 chars)');
    const filters = filtersFrom(params);
    const limit = asInteger(params.get('limit'),20,100,1);
    const digest = signature(q, filters);
    let at = 0;
    if (params.has('cursor')) {
      const c = decode(params.get('cursor'));
      if (c?.v !== this.#version || c?.h !== digest || !Number.isSafeInteger(c.at) || c.at < 0) throw new RangeError('Stale or invalid cursor');
      at = c.at;
    }
    const ranked = this.#queries.search(filters, q);
    const page = ranked.slice(at,at+limit).map(row => structuredClone(row));
    const next = at+limit < ranked.length ? encode({v:this.#version,h:digest,at:at+limit}) : null;
    return { resources:page,partialResults:next !== null,pagination:{limit:page.length,cursor:next} };
  }
  /**
   * Opt-in buyer-facing discovery. Never silently drop metered routes whose
   * authorization ceiling exceeds a buyer's expected per-call spend.
   * Comparisons are per-network, per-asset atomic units, and are not
   * authorizations or observations of settled amounts.
   */
  pricing(params = new URLSearchParams()) {
    const rawBudget = params.get('budgetAtomic');
    if (rawBudget !== null && (!params.get('network') || !params.get('asset')))
      throw new RangeError('budgetAtomic requires network and asset filters');
    const budget = rawBudget === null ? null : parseAtomicBudget(rawBudget);
    const filters = filtersFrom(params);
    const page = this.list(params);
    return {
      resources: page.resources.map(row => ({
        ...row,
        pricingView: {
          offers: describeCatalogPricing(row, filters, budget),
          budgetAtomic: rawBudget,
          note: 'Seller-declared snapshot only. Fetch live 402 and obtain buyer approval before authorization.'
        }
      })),
      pagination: page.pagination,
      pricingViewVersion: 'stellar-bazaar-pricing-v1'
    };
  }
  get size() {return this.#entries.size;}
  get version() {return this.#version;}
  /** Detached process-local diagnostics; no rows, queries or payment data. */
  get queryStats() {return this.#queries.stats;}
}

export function createDiscoveryServer(catalog) {
  // Read-only HTTP API. No endpoint permits client-injected catalog records.
  return async function handler(req,res) {
    try {
      const u = new URL(req.url,'http://localhost');
      if (req.method !== 'GET') {res.writeHead(405,{'content-type':'application/json'});res.end(JSON.stringify({error:'METHOD_NOT_ALLOWED',reason:'GET only'}));return;}
      const data = u.pathname === '/discovery/resources' ? catalog.list(u.searchParams)
        : u.pathname === '/discovery/search' ? catalog.search(u.searchParams)
        : u.pathname === '/discovery/pricing' ? catalog.pricing(u.searchParams) : null;
      if (!data) {res.writeHead(404,{'content-type':'application/json'});res.end(JSON.stringify({error:'NOT_FOUND',reason:'Unknown endpoint'}));return;}
      res.writeHead(200,{'content-type':'application/json','cache-control':'no-store'});
      res.end(JSON.stringify(data));
    } catch(e) {
      const code = e instanceof RangeError ? 400 : 500;
      res.writeHead(code,{'content-type':'application/json','cache-control':'no-store'});
      res.end(JSON.stringify({error:code===400?'INVALID_REQUEST':'INTERNAL_ERROR',reason:code===400?e.message:'Internal error'}));
    }
  };
}

// MIT. Optional seller-declared Bazaar pricing hints for a read-only catalog.
// Never use these declarations as payment authorization or proof of actual settlement.
const MODELS = new Set(['per-call','per-token','per-second','per-byte','tiered','custom']);
const I128_MAX = (1n << 127n) - 1n;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const ascii = (value, max) => typeof value === 'string' && value.length > 0 &&
  value.length <= max && /^[\x20-\x7e]+$/.test(value);

function atomic(value) {
  if (typeof value !== 'string' || !/^[0-9]{1,39}$/.test(value)) return null;
  const parsed = BigInt(value);
  return parsed <= I128_MAX ? parsed : null;
}

/** Upstream x402 extension pricing is a proposed, not yet finalized, field. */
export function sanitizeBazaarPricing(value) {
  if (!object(value) || !MODELS.has(value.model)) return null;
  const result = { model: value.model };
  const unit = value.unit;
  if (object(unit) && typeof unit.amount === 'string' &&
      /^(?:0|[1-9][0-9]*)(?:\.[0-9]+)?$/.test(unit.amount) &&
      unit.amount.length <= 40 && ascii(unit.per, 64)) {
    result.unit = { amount: unit.amount, per: unit.per };
  }
  if (atomic(value.typical) !== null) result.typical = value.typical;
  if (ascii(value.note, 256)) result.note = value.note;
  return result;
}

/** Parse a buyer's single-asset atomic-unit comparison, never a floating price. */
export function parseAtomicBudget(value) {
  const result = atomic(value);
  if (result === null) throw new RangeError('budgetAtomic must be an unsigned Stellar i128 atomic amount');
  return result;
}

/**
 * Describe ONE intact accepted payment option; never combine asset/network/payTo
 * or infer that a metered ceiling is the eventual debit.
 * `typical` is seller-declared, never a proven median or a spending authority.
 */
export function describePricingOption(option, pricing = null, budgetAtomic = null,
  { typicalUnambiguous = true } = {}) {
  const scheme = option?.scheme;
  const limit = atomic(option?.amount);
  const isFixed = scheme === 'exact';
  const isMetered = scheme === 'upto';
  const sellerTypical = typicalUnambiguous && isMetered && limit !== null &&
    atomic(pricing?.typical) !== null && atomic(pricing.typical) <= limit
    ? pricing.typical : null;
  const result = {
    network: option?.network ?? null,
    asset: option?.asset ?? null,
    payTo: option?.payTo ?? null,
    scheme: scheme ?? null,
    amountAtomic: typeof option?.amount === 'string' ? option.amount : null,
    amountMeaning: isFixed ? 'ADVERTISED_FIXED_PRICE' :
      isMetered ? 'MAXIMUM_AUTHORIZATION_NOT_SETTLED_PRICE' : 'UNKNOWN_SCHEME',
    pricingModel: pricing?.model ?? null,
    sellerClaimedTypicalAtomic: sellerTypical,
    observedSettledAmountAtomic: null,
    requiresFresh402AndBuyerApproval: true
  };
  if (budgetAtomic === null) return result;
  const budget = typeof budgetAtomic === 'bigint' ? budgetAtomic : parseAtomicBudget(budgetAtomic);
  if (limit === null || (!isFixed && !isMetered)) result.budgetAssessment = 'NOT_COMPARABLE';
  else if (isFixed) result.budgetAssessment = limit <= budget ?
    'ADVERTISED_PRICE_WITHIN_BUDGET' : 'ADVERTISED_PRICE_ABOVE_BUDGET';
  else if (limit <= budget) result.budgetAssessment = 'AUTHORIZATION_CEILING_WITHIN_BUDGET';
  else if (sellerTypical === null) result.budgetAssessment = 'CEILING_ABOVE_BUDGET_COST_UNKNOWN';
  else result.budgetAssessment = atomic(sellerTypical) <= budget ?
    'CEILING_ABOVE_BUDGET_SELLER_TYPICAL_WITHIN' :
    'CEILING_ABOVE_BUDGET_SELLER_TYPICAL_ABOVE';
  return result;
}

/** Nonmutating view over only the caller's same-option filtered accepts. */
export function describeCatalogPricing(entry, filters = {}, budgetAtomic = null) {
  const paymentKeys = ['network','asset','scheme','payTo'].filter(k =>
    Object.hasOwn(filters, k));
  const offers = (entry?.accepts ?? []).filter(option =>
    paymentKeys.every(key => option?.[key] === filters[key]));
  const distinctDenominations = new Set(offers.map(o => `${o?.network}\u0000${o?.asset}`));
  const pricing = sanitizeBazaarPricing(entry?.extensions?.bazaar?.pricing);
  return offers.map(option => describePricingOption(option, pricing, budgetAtomic, {
    typicalUnambiguous: distinctDenominations.size === 1
  }));
}

// MIT. Private read-side acceleration for the authoritative BazaarCatalog Map.
// Indexes narrow candidates; they never validate, admit, retire or pay for an offer.
import { rankBazaarEntries } from './ranking.mjs';

const PAYMENT_KEYS = ['payTo', 'network', 'scheme', 'asset'];
const MAX_RESULTS = 64;
const MAX_REFERENCES = 200_000;

function matches(row, filters) {
  if (Object.hasOwn(filters, 'type') && row.extensions?.bazaar?.info?.input?.type !== filters.type) return false;
  if (Object.hasOwn(filters, 'extensions') && !Object.hasOwn(row.extensions, filters.extensions)) return false;
  // Intersecting per-field postings is only a candidate reduction: all payment
  // fields MUST still match the SAME original accepted option, never a hybrid.
  const keys = PAYMENT_KEYS.filter(key => Object.hasOwn(filters, key));
  return !keys.length || row.accepts.some(option =>
    keys.every(key => option?.[key] === filters[key]));
}

function dimensions(row) {
  const result = new Map([
    ['type', new Set([row.extensions?.bazaar?.info?.input?.type])],
    ['extensions', new Set(Object.keys(row.extensions))],
  ]);
  for (const key of PAYMENT_KEYS) result.set(key, new Set(row.accepts
    .map(option => option[key]).filter(value => typeof value === 'string')));
  return result;
}

/** Internal ownership contract: entries and returned row references stay inside
 * BazaarCatalog. Its public reads clone pages. Call changed AFTER each Map write;
 * a catalog clone owns a fresh Map and a fresh index, never another clone's cache.
 */
export class CatalogQueryIndex {
  #entries;
  #postings = new Map();
  #ordinals = new Map();
  #nextOrdinal = 0;
  #ready = false;
  #ordered = null;
  #cache = new Map();
  #references = 0;
  #counts = { indexBuilds: 0, orderBuilds: 0, candidateChecks: 0,
    listHits: 0, listMisses: 0, searchHits: 0, searchMisses: 0, rankRuns: 0,
    evictions: 0, invalidations: 0 };

  constructor(entries) { this.#entries = entries; }

  #post(id, row, add) {
    for (const [field, values] of dimensions(row)) {
      let fieldIndex = this.#postings.get(field);
      if (!fieldIndex && add) this.#postings.set(field, fieldIndex = new Map());
      if (!fieldIndex) continue;
      for (const value of values) {
        let ids = fieldIndex.get(value);
        if (add) {
          if (!ids) fieldIndex.set(value, ids = new Set());
          ids.add(id);
        } else if (ids) {
          ids.delete(id);
          if (!ids.size) fieldIndex.delete(value);
        }
      }
      if (!fieldIndex.size) this.#postings.delete(field);
    }
  }

  #ensureIndex() {
    if (this.#ready) return;
    for (const [id, row] of this.#entries) {
      this.#ordinals.set(id, this.#nextOrdinal++);
      this.#post(id, row, true);
    }
    this.#ready = true;
    this.#counts.indexBuilds++;
  }

  changed(id, before, after) {
    // An update replaces the Map's value without changing its insertion order.
    // Delete/reinsert DOES get a new ordinal, exactly like the original Map.
    if (this.#ready) {
      if (before !== undefined) this.#post(id, before, false);
      if (after !== undefined) {
        if (before === undefined) this.#ordinals.set(id, this.#nextOrdinal++);
        this.#post(id, after, true);
      } else this.#ordinals.delete(id);
    }
    if (before === undefined || after === undefined) this.#ordered = null;
    this.#cache.clear();
    this.#references = 0;
    this.#counts.invalidations++;
  }

  #candidateIds(filters) {
    const fields = Object.entries(filters);
    if (!fields.length) return [...this.#entries.keys()];
    this.#ensureIndex();
    const sets = [];
    for (const [field, value] of fields) {
      const ids = this.#postings.get(field)?.get(value);
      if (!ids) return [];
      sets.push(ids);
    }
    sets.sort((a, b) => a.size - b.size);
    const [smallest, ...rest] = sets, result = [];
    for (const id of smallest) {
      if (!rest.every(ids => ids.has(id))) continue;
      this.#counts.candidateChecks++;
      if (matches(this.#entries.get(id), filters)) result.push(id);
    }
    return result;
  }

  #memo(kind, filters, query, compute) {
    // Offset, limit and cursor select a page, not a different result set. The
    // caller checks cursor generation BEFORE this lookup; hits cannot revive it.
    const key = JSON.stringify([kind, query, Object.entries(filters).sort(([a], [b]) => a.localeCompare(b))]);
    const hit = this.#cache.get(key);
    if (hit !== undefined) {
      this.#cache.delete(key); this.#cache.set(key, hit);
      this.#counts[kind + 'Hits']++;
      return hit;
    }
    this.#counts[kind + 'Misses']++;
    const result = compute(); // Invalid queries are not retained as cache entries.
    if (result.length <= MAX_REFERENCES) {
      while (this.#cache.size >= MAX_RESULTS || this.#references + result.length > MAX_REFERENCES) {
        const oldest = this.#cache.keys().next().value;
        this.#references -= this.#cache.get(oldest).length;
        this.#cache.delete(oldest); this.#counts.evictions++;
      }
      this.#cache.set(key, result); this.#references += result.length;
    }
    return result;
  }

  list(filters) {
    return this.#memo('list', filters, null, () => {
      let ids;
      if (!Object.keys(filters).length) {
        if (this.#ordered === null) {
          this.#ordered = [...this.#entries.keys()].sort((a, b) => a.localeCompare(b));
          this.#counts.orderBuilds++;
        }
        ids = this.#ordered;
      } else {
        ids = this.#candidateIds(filters);
        // Locale comparison can tie for distinct Unicode keys. Use Map insertion
        // order for that tie, matching the original stable full-catalog sort.
        ids.sort((a, b) => a.localeCompare(b) || this.#ordinals.get(a) - this.#ordinals.get(b));
      }
      return ids.map(id => this.#entries.get(id));
    });
  }

  search(filters, query) {
    return this.#memo('search', filters, query, () => {
      const ids = this.#candidateIds(filters);
      // Preserve the original corpus iteration order as well as corpus membership:
      // ranking's floating-point reductions and stable ties must remain identical.
      if (Object.keys(filters).length) ids.sort((a, b) => this.#ordinals.get(a) - this.#ordinals.get(b));
      this.#counts.rankRuns++;
      return rankBazaarEntries(ids.map(id => [id, this.#entries.get(id)]), query).map(item => item.row);
    });
  }

  get stats() {
    return { ...this.#counts, indexedEntries: this.#ready ? this.#ordinals.size : 0,
      cachedResults: this.#cache.size, cachedReferences: this.#references,
      maxCachedResults: MAX_RESULTS, maxCachedReferences: MAX_REFERENCES };
  }
}

// MIT. Deterministic, dependency-free lexical/fuzzy ranking for validated x402 Bazaar records.
// This module only reads already trusted catalog rows; it never ingests payment payloads.
const STOP = new Set([
  'a','an','and','are','can','could','find','for','get','give','i','in','is','me',
  'my','of','on','or','please','show','that','the','to','want','which','with','you'
]);
const NORMALIZE = s => String(s ?? '').normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase();
export const tokenize = s => NORMALIZE(s).match(/[\p{L}\p{N}]+/gu) ?? [];
const words = s => tokenize(typeof s === 'string' ? s.slice(0,2048) : '');
const object = o => o !== null && typeof o === 'object' && !Array.isArray(o);
const field = (text, weight) => ({ tokens: words(text).slice(0,128), weight });

function toFields(row) {
  const resource = object(row.resource) ? row.resource : {};
  const info = object(row.extensions?.bazaar?.info) ? row.extensions.bazaar.info : {};
  const input = object(info.input) ? info.input : {};
  const props = object(input.inputSchema?.properties) ? input.inputSchema.properties : {};
  const parameters = Object.entries(props).slice(0,32).map(([name, spec]) =>
    name+' '+(object(spec) && typeof spec.description === 'string' ? spec.description : '')).join(' ');
  return [
    field(resource.serviceName, 9),
    field(Array.isArray(resource.tags) ? resource.tags.filter(x => typeof x === 'string').slice(0,16).join(' ') : '', 7),
    field(input.toolName, 8),
    field(input.description, 4),
    field(resource.description, 4),
    field(parameters, 2),
    field(resource.url, 0.6)
  ];
}

// Small, bounded edit distance prevents a misspelled merchant/tool name from vanishing.
// Never uses fuzzy scores as proof of semantic equivalence.
function editDistanceWithin(a, b, limit) {
  if (Math.abs(a.length - b.length) > limit) return false;
  if (a === b) return true;
  // The caller permits at most one or two substitutions/insertions/deletions.
  // Cells farther than `limit` from the diagonal cannot change the answer;
  // only allocate/visit that narrow band, rather than O(a.length*b.length).
  const beyond = limit + 1;
  const n = b.length;
  let previousStart = 0;
  let previousEnd = Math.min(n, limit);
